* {
    font-family: "JetBrainsMono Nerd Font";
    font-size: 13px;
    background: none;
}

window#waybar {
    background: transparent;
}


.modules-left,
.modules-center,
.modules-right{
    background: rgba(30, 30, 46, 0.85);
    border-radius: 8px;
    margin: 6px 4px;
    padding: 0 5px;
}

#workspaces button.active {
    background: #89b4fa;
    color: #1e1e2e;
    border-radius: 5px;
}

